import * as THREE from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  mix,
  color,
  uv,
  vec2,
  add,
  texture,
  nodeObject,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives'; // primitives are accessed via ctx.primitives
import { createTextMesh } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @typedef {Object} NodeContext
 */

/**
 * Creates the oversized editorial type node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  /*** Root group ***/
  const root = new THREE.Group();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  /*** Helper lists for cleanup ***/
  const disposables = [];

  /*** Background plate – vertical engineered gradient ***/
  const bgGeom = new THREE.PlaneGeometry(7, 5.5);
  const bgMat = new MeshBasicNodeMaterial({
    colorNode: mix(
      color('#0b0b10'), // top
      color('#14141a'), // bottom
      uv().y
    ),
    transparent: false,
    side: THREE.DoubleSide,
  });
  const bgMesh = new THREE.Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -0.1);
  root.add(bgMesh);
  disposables.push(bgGeom, bgMat, bgMesh);

  /*** Text style helpers ***/
  const colors = {
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38'),
  };

  const leftX = -3.1;
  const baseline = 0.25;

  /*** Kicker ***/
  const kickerOpts = {
    fontFamily: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 18,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    color: colors.ink,
    align: 'left',
    uppercase: true,
  };
  const kicker = createTextMesh('NOVA ATELIER / JOURNAL', kickerOpts);
  kicker.position.set(leftX, 1.7, 0);
  kicker.material.transparent = true;
  kicker.material.opacity = 0;
  root.add(kicker);
  disposables.push(kicker);

  /*** Hero lines ***/
  const heroOpts = {
    fontFamily: 'Lora',
    fontWeight: 600,
    fontSize: 124,
    letterSpacing: -0.015,
    lineHeight: 0.98,
    color: colors.ink,
    align: 'left',
    uppercase: false,
  };

  const heroLine1 = createTextMesh('PRECISION IS', heroOpts);
  heroLine1.position.set(leftX, 0.9, 0);
  heroLine1.material.transparent = true;
  heroLine1.material.opacity = 0;
  root.add(heroLine1);
  disposables.push(heroLine1);

  // shadow for line1
  const heroLine1Shadow = heroLine1.clone();
  heroLine1Shadow.position.z -= 0.02;
  heroLine1Shadow.material = heroLine1Shadow.material.clone();
  heroLine1Shadow.material.color = colors.ink;
  root.add(heroLine1Shadow);
  disposables.push(heroLine1Shadow);

  const heroLine2 = createTextMesh('A HABIT.', heroOpts);
  heroLine2.position.set(leftX, 0.25, 0);
  heroLine2.material.transparent = true;
  heroLine2.material.opacity = 0;
  root.add(heroLine2);
  disposables.push(heroLine2);

  // shadow for line2
  const heroLine2Shadow = heroLine2.clone();
  heroLine2Shadow.position.z -= 0.02;
  heroLine2Shadow.material = heroLine2Shadow.material.clone();
  heroLine2Shadow.material.color = colors.ink;
  root.add(heroLine2Shadow);
  disposables.push(heroLine2Shadow);

  /*** Body paragraph ***/
  const bodyOpts = {
    fontFamily: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 26,
    letterSpacing: 0,
    lineHeight: 1.55,
    color: colors.ink,
    align: 'left',
    maxWidth: 4.5,
    uppercase: false,
  };
  const bodyText =
    'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.';
  const body = createTextMesh(bodyText, bodyOpts);
  body.position.set(leftX, -0.8, 0);
  body.material.transparent = true;
  body.material.opacity = 0;
  root.add(body);
  disposables.push(body);

  /*** Caption ***/
  const captionOpts = {
    fontFamily: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 18,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: colors.ink,
    align: 'left',
    uppercase: true,
  };
  const caption = createTextMesh('ISSUE 12 / JULY 2026', captionOpts);
  caption.position.set(leftX, -1.9, 0);
  caption.material.transparent = true;
  caption.material.opacity = 0;
  root.add(caption);
  disposables.push(caption);

  /*** Accent underline rule ***/
  const ruleGeom = new THREE.PlaneGeometry(2.2, 0.05);
  const ruleMat = new MeshBasicNodeMaterial({
    colorNode: color('#ff2a38'),
    emissiveNode: color('#ff2a38').mul(1.2),
    transparent: true,
  });
  const rule = new THREE.Mesh(ruleGeom, ruleMat);
  // Center rule under the left-aligned text
  rule.position.set(leftX + 1.1, -0.15, 0.01);
  rule.scale.set(0, 1, 1); // start collapsed on X
  root.add(rule);
  disposables.push(ruleGeom, ruleMat, rule);

  /*** Prepare entrance animation (rise‑in) ***/
  const timeline = gsap.timeline({ defaults: { ease: 'cubic-bezier(0.215,0.61,0.355,1)' } });

  const blocks = [
    { obj: kicker, targetY: kicker.position.y },
    { obj: heroLine1, targetY: heroLine1.position.y },
    { obj: heroLine2, targetY: heroLine2.position.y },
    { obj: body, targetY: body.position.y },
    { obj: caption, targetY: caption.position.y },
  ];

  blocks.forEach((b, i) => {
    // start offset
    b.obj.position.y = b.targetY + 0.4;
    // ensure material opacity starts at 0 (already set)
    timeline
      .to(
        b.obj.position,
        {
          y: b.targetY,
          duration: 0.7,
        },
        i * 0.08
      )
      .to(
        b.obj.material,
        {
          opacity: 1,
          duration: 0.7,
        },
        i * 0.08
      );
  });

  // After the second hero line lands, draw the rule
  const hero2EndTime = 0.08 * 2 + 0.7; // start offset + duration
  timeline.add(
    () => {
      gsap.to(rule.scale, {
        x: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
    },
    hero2EndTime
  );

  timeline.play();

  /*** Cleanup ***/
  root.userData.handlers = {}; // placeholder for potential future handlers
  root.userData.cleanup = () => {
    timeline.kill();
    disposables.forEach((d) => {
      if (d && d.dispose) d.dispose();
      if (d && d.geometry) d.geometry.dispose();
      if (d && d.material) d.material.dispose();
    });
  };

  return root;
}
